export type JobPolicy = "read-only" | "worktree-write";
export const JOB_POLICIES: readonly JobPolicy[] = ["read-only", "worktree-write"];

export type JobOrigin = { kind: "cli" } | { kind: "schedule"; scheduleId: string; dueAt: string };

