    const onTime = !all.truncated && now - all.last <= grace;
    const lateScan = onTime ? (all.count > 1 ? scanSlots(original.trigger, anchor, due - 1, all.last - 1) : undefined) : all;
    const late: ScheduleMissedSummary | null = lateScan && lateScan.count > 0 && lateScan.first !== undefined && lateScan.last !== undefined
      ? { count: lateScan.count, first: iso(lateScan.first), last: iso(lateScan.last), ...(lateScan.truncated ? { truncated: true as const } : {}) }
      : null;
    const current = onTime ? all.last : undefined;
    const slotsOf = (from: ScheduleMissedSummary | null, extra?: number): ScheduleMissedSummary | null =>
      from === null && extra === undefined ? null : from ?? { count: 1, first: iso(extra!), last: iso(extra!) };

    // Overlap: the schedule's previous job is still running.
    const running = own.some((job) => !isTerminal(job.state));
    if (running) return this.record(original, now, all.last, slotsOf(late, current)?.count === undefined ? null : { count: all.count, first: iso(all.first!), last: iso(all.last), ...(all.truncated ? { truncated: true as const } : {}) }, "overlap", undefined, "SKIPPED_OVERLAP");

    // Which slot the job stands for: the newest on-time slot, or (catch-up) the last late one.
    const kind = current !== undefined ? "scheduled" : original.onMissed === "run-once" ? "catch_up" : undefined;
    const dueAt = current ?? (kind === "catch_up" ? Date.parse(late!.last) : undefined);
    if (kind === undefined || dueAt === undefined) return this.record(original, now, all.last, late, "runner_not_running", undefined, "MISSED");

    // A job already made for this slot (a runner that died after submitting, or a clock stepped back over it) is not made twice.
    if (own.some((job) => job.origin.kind === "schedule" && job.origin.dueAt === iso(dueAt))) return this.advance(original, now, all.last);

    if (!this.options.workspaceListed(original.workspace)) {
      return this.refuse(original, now, all.last, late, current, "the workspace is not in the trusted-workspace list (run `nexus trust` for it)");
    }
    let job: JobSubmission;
    try {
      const built = submissionFor(original, iso(dueAt));
      this.options.submit(built.job, built.spec);
      job = built.job;
    } catch (error) {
      return this.refuse(original, now, all.last, late, current, error instanceof Error ? error.message : String(error));
    }
    this.options.log(`schedule ${original.id}: ${kind === "catch_up" ? "catch-up " : ""}job ${job.id} for ${iso(dueAt)}${late ? ` (${late.count} slot${late.count === 1 ? "" : "s"} missed before it)` : ""}`);
    let next = this.advance({ ...original, state: { ...original.state, lastFire: { jobId: job.id, dueAt: iso(dueAt), kind, firedAt: this.options.now().toISOString(), missed: late } } }, now, all.last);
    next = { ...next, remainingRuns: next.remainingRuns === null ? null : next.remainingRuns - 1 };
    if (next.remainingRuns === 0) next = { ...next, enabled: false };
    if (late) next = this.report(next, late, "runner_not_running", { jobId: job.id, action: kind === "catch_up" ? "catch_up" : "none" });
    return next;
  }

  private refuse(record: ScheduleRecord, now: number, last: number, late: ScheduleMissedSummary | null, current: number | undefined, why: string): ScheduleRecord {
    this.options.log(`schedule ${record.id}: the run for ${iso(current ?? Date.parse(late?.last ?? iso(last)))} was refused: ${why}`);
    const slots = late ?? { count: 1, first: iso(last), last: iso(last) };
    const covered = late && current !== undefined ? { count: late.count + 1, first: late.first, last: iso(current), ...(late.truncated ? { truncated: true as const } : {}) } : slots;
    return this.record(record, now, last, covered, "refused", why, "REFUSED");
  }

  /** Records a gap with no job, advances past `now`. */
  private record(record: ScheduleRecord, now: number, last: number, gap: ScheduleMissedSummary | null, reason: ScheduleMissReason, detail: string | undefined, outcome: "MISSED" | "SKIPPED_OVERLAP" | "REFUSED"): ScheduleRecord {
    const advanced = this.advance(record, now, last);
    const reported = gap ? this.report(advanced, gap, reason, { action: "none", ...(detail ? { detail } : {}) }) : advanced;
    return { ...reported, state: { ...reported.state, lastOutcome: outcome } };
  }

  /** Moves past `now`: the next slot strictly after it, or none for a `once`. A `once` ends here whatever happened. */
  private advance(record: ScheduleRecord, now: number, last: number | undefined): ScheduleRecord {
    const again = record.trigger.kind === "once" ? undefined : nextAfter(record.trigger, Date.parse(record.createdAt), now);
    return {
      ...record,
      enabled: record.trigger.kind === "once" ? false : record.enabled,
      state: { ...record.state, nextDueAt: again === undefined ? null : iso(again), ...(last !== undefined ? { lastDueAt: iso(last) } : {}), lastTickAt: iso(now) },
    };
  }

  /** The gap in the record and as a receipt of its own. */
  private report(record: ScheduleRecord, gap: ScheduleMissedSummary, reason: ScheduleMissReason, extra: { jobId?: string; action: "catch_up" | "none"; detail?: string }): ScheduleRecord {
    const reportedAt = this.options.now().toISOString();
    const entry: ScheduleMissedGap = { ...gap, reason, reportedAt, ...(extra.detail ? { detail: extra.detail.slice(0, 500) } : {}) };
    try {
      writePrivateJson(this.paths.missed(record.id, gap.first), parseScheduleMissedReceipt({
        format: "nexus-schedule-missed", version: 1, scheduleId: record.id, outcome: "MISSED", reason, count: gap.count, first: gap.first, last: gap.last, ...(gap.truncated ? { truncated: true } : {}), reportedAt,
        action: extra.action, ...(extra.jobId ? { jobId: extra.jobId } : {}), ...(entry.detail ? { detail: entry.detail } : {}),
      }));
      pruneMissedReceipts(this.paths, record.id);
    } catch (error) {
      this.options.log(`schedule ${record.id}: the missed-run receipt could not be written: ${error instanceof Error ? error.message : String(error)}`);
    }
    this.options.log(`schedule ${record.id}: ${gap.count}${gap.truncated ? "+" : ""} slot${gap.count === 1 ? "" : "s"} missed (${reason}) from ${gap.first} to ${gap.last}`);
    return {
      ...record,
      state: { ...record.state, missedCount: record.state.missedCount + gap.count, missed: [...record.state.missed, entry].slice(-MAX_MISSED_GAPS) },
    };
  }
}

