    n === 1
      ? { kind: "tools", calls: [{ name: "write_file", args: { path: "made.txt", content: "made by the schedule\n" } }, command, command] }
      : { kind: "tools", calls: [{ name: "task_completed", args: { summary: "wrote made.txt" } }] },
  );
